#!/usr/bin/python3
import os
import sys
import time

BASE = os.path.dirname(os.path.abspath(__file__))
RESULTS = os.path.join(BASE, "results.tsv")


def requested_jobs(argv):
    if len(argv) != 2:
        raise SystemExit("usage: %s JOB_COUNT" % argv[0])
    try:
        count = int(argv[1])
    except ValueError:
        raise SystemExit("JOB_COUNT must be a non-negative integer")
    if count < 0:
        raise SystemExit("JOB_COUNT must be a non-negative integer")
    return count


def child_job(number):
    time.sleep(0.1)
    os._exit(0 if number % 2 == 0 else 3)


def main():
    count = requested_jobs(sys.argv)
    children = {}

    for number in range(count):
        pid = os.fork()
        if pid == 0:
            child_job(number)
        children[pid] = number

    statuses = {}
    while children:
        try:
            pid, wait_status = os.waitpid(-1, 0)
        except InterruptedError:
            continue

        number = children.pop(pid)
        if os.WIFEXITED(wait_status):
            statuses[number] = os.WEXITSTATUS(wait_status)
        elif os.WIFSIGNALED(wait_status):
            statuses[number] = 128 + os.WTERMSIG(wait_status)

    run_id = "%d-%d" % (int(time.time()), os.getpid())
    needs_header = not os.path.exists(RESULTS) or os.path.getsize(RESULTS) == 0
    delimiter = "\t"
    if not needs_header:
        with open(RESULTS, "r") as existing:
            header = existing.readline()
        if "," in header and "\t" not in header:
            delimiter = ","

    with open(RESULTS, "a") as output:
        if needs_header:
            output.write(delimiter.join(("run", "job", "exit_status")) + "\n")
        for number in sorted(statuses):
            output.write(delimiter.join((run_id, str(number), str(statuses[number]))) + "\n")


if __name__ == "__main__":
    main()
